SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT tags AS tags, timestamp AS timestamp, if(length(buckets) < 2 OR NOT isInfinite(tupleElement(arrayElement(buckets, length(buckets)), 1)) OR arrayExists(v -> isNaN(v), arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 2), nan)), buckets)), nan, arraySum(arrayMap((delta, midpoint) -> delta * midpoint, arrayMap((count, prev_count) -> if(count - prev_count < 0, toFloat64(0), count - prev_count), arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 2), nan)), buckets), arrayConcat([toFloat64(0)], arrayPopBack(arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 2), nan)), buckets)))), arrayMap((lower, upper) -> if(isNaN(lower) OR isNaN(upper) OR isInfinite(lower) OR isInfinite(upper), toFloat64(0), lower + (upper - lower) / 2), arrayMap((idx, upper, prev_upper) -> if(idx = 1 AND upper <= 0, upper, prev_upper), arrayEnumerate(arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 1), nan)), buckets)), arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 1), nan)), buckets), arrayConcat([toFloat64(0)], arrayPopBack(arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 1), nan)), buckets)))), arrayMap((upper, prev_upper) -> if(isInfinite(upper), prev_upper, upper), arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 1), nan)), buckets), arrayConcat([toFloat64(0)], arrayPopBack(arrayMap(bucket -> toFloat64(ifNull(tupleElement(bucket, 1), nan)), buckets)))))))) AS value FROM (SELECT histogram_tags AS tags, timestamp AS timestamp, arraySort(item -> item.1, groupArray((upper_bound, cumulative_count))) AS buckets FROM (SELECT histogram_tags AS histogram_tags, timestamp AS timestamp, upper_bound AS upper_bound, sum(cumulative_count) AS cumulative_count FROM (SELECT arrayFilter(tag -> tag.1 != 'le' AND tag.1 != '__name__', tags) AS histogram_tags, point.1 AS timestamp, multiIf(le_raw IN ['+Inf', 'Inf', '+inf', 'inf'], inf, le_raw IN ['-Inf', '-inf'], -inf, toFloat64OrNull(le_raw)) AS upper_bound, ifNull(toFloat64(point.2), nan) AS cumulative_count FROM (SELECT tags AS tags, time_series AS time_series, tupleElement(arrayFirst(tag -> tag.1 = 'le', tags), 2) AS le_raw FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({histogram_projection_child_start_ms:Int64}, {histogram_projection_child_end_ms:Int64} + {histogram_projection_child_step_ms:Int64}, {histogram_projection_child_step_ms:Int64}))) AS eval_ts FROM (
            SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {histogram_projection_child_range_instant_matcher_0_value:String} AND src.tags[concat('', {histogram_projection_child_range_instant_matcher_1_key:String})] = {histogram_projection_child_range_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({histogram_projection_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({histogram_projection_child_required_end_ms:Int64})
        ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({histogram_projection_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({histogram_projection_child_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({histogram_projection_child_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({histogram_projection_child_offset_ms:Int64} + {histogram_projection_child_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) AS histogram_child) AS histogram_series ARRAY JOIN histogram_series.time_series AS point WHERE le_raw != '' AND upper_bound IS NOT NULL) AS histogram_rows GROUP BY histogram_tags, timestamp, upper_bound) AS coalesced_histogram_rows GROUP BY histogram_tags, timestamp) AS classic_histograms ORDER BY tags, timestamp) AS histogram_projection_steps GROUP BY tags ORDER BY tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
